          "ሰው ምድራዊ ፍላጎቶቹን እንዲፈጽምለት ፈጣሪን የማዘዝ አስማታዊ ስልጣን ያገኛል።",
          "ፈጣሪ የዕለት ተዕለት ውይይቶችን ለማድረግ በተማሪው ክፍል ውስጥ በአካላዊ ቅርጽ ይገለጣል።",
